"""Synset-level countability for article resolution.

Contains a frozenset of WordNet synset names that should never take an
indefinite article ("a"/"an") in generated templates.  Bootstrapped by
running Sonnet classification over all synsets that appear in ``{a_X}``
template slots across seeds 0-49, then verified with a conservative
second pass.

CONTEXT_DEPENDENT synsets default to countable (i.e. they keep the
article), since "a fish has fins" is less wrong than dropping the
article from a truly countable noun.

To maintain: if QA catches an article error, add or remove the synset
name here and re-run tests.  Keep entries sorted alphabetically.
"""

